function renderPlatformCards(){const grid=$('#platform-grid');if(!grid)return;const platforms=[...new Set(services.map(s=>s.platform))],preferred=['Instagram','TikTok','YouTube','X / Twitter','Telegram','Facebook','WhatsApp','Spotify','Twitch','Kick'],ordered=[...preferred,...platforms.filter(p=>!preferred.includes(p))];const expanded=grid.dataset.expanded==='true',visible=expanded?ordered:ordered.slice(0,10);grid.innerHTML=visible.map(platform=>{const list=services.filter(s=>s.platform===platform),minimum=list.length?Math.min(...list.map(s=>s.salePrice)):0,meta=platformMeta[platform]||['Aktif sosyal medya hizmetleri'];return '<button class="category-card '+platform.toLocaleLowerCase('tr').replace(/[^a-z]/g,'')+'" data-platform="'+escapeHtml(platform)+'"><b>'+platformLogo(platform)+'</b><span>'+escapeHtml(platform)+'<small>'+escapeHtml(catalogText(meta[0]))+'</small><strong>'+servicePriceLabel(list.sort((a,b)=>a.salePrice-b.salePrice)[0]||{})+' '+catalogLabel('starting')+'</strong></span><em>'+list.length+' '+catalogLabel('service')+'</em></button>'}).join('')+(ordered.length>10?'<button class="platform-more" type="button" aria-expanded="'+expanded+'">'+(expanded?'Daha az gÃ¶ster':'Daha fazla gÃ¶ster ('+ordered.length+')')+'</button>':'');grid.querySelectorAll('[data-platform]').forEach(button=>button.onclick=()=>platformFilter(button.dataset.platform));grid.querySelector('.platform-more')?.addEventListener('click',()=>{grid.dataset.expanded=String(!expanded);renderPlatformCards()})}
let selectedPlatform='';function setOrderStep(step){$$('.order-steps .step').forEach((node,index)=>{node.classList.toggle('active',index+1===step);node.classList.toggle('done',index+1<step)})}function chooseOrderPlatform(platform){selectedPlatform=platform;$$('[data-platform-pick]').forEach(button=>{const active=button.dataset.platformPick===platform;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))});const categoryPlatform=platform==='Twitter'?'X / Twitter':platform;const matching=services.filter(service=>cleanServiceName(service.platform)===cleanServiceName(platform)||cleanServiceName(service.platform)===cleanServiceName(categoryPlatform));const categories=[...new Set(matching.map(service=>service.platform+' Â· '+service.category))].sort((a,b)=>a.localeCompare(b,'tr'));$('#category-select').innerHTML='<option value="">'+(categories.length?catalogLabel('chooseCategory'):catalogLabel('noCategory'))+'</option>'+categories.map(value=>'<option value="'+escapeHtml(value)+'">'+escapeHtml(catalogText(cleanServiceName(value)))+'</option>').join('');$('#service-select').innerHTML='<option value="">'+catalogLabel('chooseService')+'</option>'+matching.map(service=>'<option value="'+service.id+'">'+escapeHtml(catalogText(service.name))+'</option>').join('');const categorySelect=$('#category-select'),serviceSelect=$('#service-select');categorySelect.value='';categorySelect.dispatchEvent(new Event('change',{bubbles:true}));selectedService=null;$('#service-id').value='';updatePrice();setOrderStep(2)}
function renderProviderFields(service){const host=$('#dynamic-service-fields');if(!host)return;const fields=Array.isArray(service?.providerFields)?service.providerFields:[];host.innerHTML=fields.filter(f=>f&&f.name&&!['link','quantity','service'].includes(String(f.name))).map(f=>{const name=String(f.name),label=escapeHtml(catalogText(f.label||name)),required=f.required!==false,type=String(f.type||'text'),attrs=' data-provider-field name="'+escapeHtml(name)+'" '+(required?'required ':'')+(f.min!=null?'min="'+Number(f.min)+'" ':'')+(f.max!=null?'max="'+Number(f.max)+'" ':'');const input=type==='text_lines'?'<textarea'+attrs+' rows="3"></textarea>':'<input'+attrs+'type="'+(['url','integer','number'].includes(type)?(type==='integer'?'number':type):'text')+'" '+(['integer','number'].includes(type)?'step="1" ':'')+'>';return '<label>'+label+input+(f.description?'<small>'+escapeHtml(catalogText(f.description))+'</small>':'')+'</label>'}).join('')}$('#service-select').onchange=e=>{selectedService=services.find(x=>x.id===Number(e.target.value))||null;$('#service-id').value=selectedService?.id||'';renderProviderFields(selectedService);if(selectedService){$('#quantity').min=selectedService.minOrder;$('#quantity').max=selectedService.maxOrder;$('#quantity').placeholder=selectedService.minOrder;const perOrder=selectedService.priceUnit==='per_order';$('#service-info').innerHTML='<span>âœ¦</span><p><b>'+escapeHtml(catalogText(cleanServiceName(selectedService.name)))+'</b><br>'+catalogLabel('limit')+': '+Number(selectedService.minOrder).toLocaleString(currentLanguage)+'â€“'+Number(selectedService.maxOrder).toLocaleString(currentLanguage)+' Â· '+(perOrder?'SipariÅŸ baÅŸÄ±na ':' '+catalogLabel('pricePerThousand')+' ')+money(selectedService.salePrice/100)+(selectedService.description?' Â· '+escapeHtml(catalogText(selectedService.description)):'')+'</p>'}updatePrice();setOrderStep(selectedService?3:2)};
$('#quantity').oninput=()=>{updatePrice();setOrderStep(Number($('#quantity').value)>0?4:selectedService?3:2)};const orderLink=$('#order-form [name=link]');orderLink?.addEventListener('input',()=>{if(selectedService&&orderLink.value)setOrderStep(Number($('#quantity').value)>0?4:3)});function updatePrice(){const q=Number($('#quantity').value||0),amount=selectedService?(selectedService.priceUnit==='per_order'?selectedService.salePrice/100:q*(selectedService.salePrice/100)/1000):0;$('#amount').textContent=money(amount);$('#amount-input').value=amount.toFixed(2)}setOrderStep(1)
