function renderPopular(){const el=$('#popular-services');if(!services.length){el.innerHTML='<p style="color:#718096;font-size:10px;padding:20px 0">'+catalogLabel('automated')+'</p>';return}el.innerHTML=services.slice(0,4).map(s=>'<button class="service-chip" data-id="'+s.id+'"><span>'+platformLogo(s.platform)+'</span><div><b>'+escapeHtml(catalogText(cleanServiceName(s.name)))+'</b><small>'+escapeHtml(catalogText(cleanServiceName(s.platform)))+' Â· '+escapeHtml(catalogText(cleanServiceName(s.category)))+'</small></div><strong>'+money(s.salePrice/100)+'</strong></button>').join('');el.querySelectorAll('button').forEach(b=>b.onclick=()=>chooseService(Number(b.dataset.id)))}function renderNewServices(){const host=$('#new-services-list'),title=$('#new-services-title'),note=$('#new-services-note');if(!host)return;if(title)title.textContent=catalogLabel('newTitle');if(note)note.textContent=catalogLabel('newNote');const fresh=services.filter(s=>s.isNew===true||s.isNew===1||s.isNew==='1').sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0)).slice(0,8);host.innerHTML=fresh.length?fresh.map(s=>'<button class="service-chip new-service-chip" data-id="'+s.id+'"><span>'+platformLogo(s.platform)+'</span><div><b>'+escapeHtml(catalogText(cleanServiceName(s.name)))+'</b><small>'+escapeHtml(catalogText(cleanServiceName(s.platform)))+' Â· '+escapeHtml(catalogText(cleanServiceName(s.category)))+' Â· <em class="new-service-badge">'+escapeHtml(catalogLabel('newBadge'))+'</em></small></div><strong>'+servicePriceLabel(s)+'</strong></button>').join(''):'<p class="new-services-empty">'+catalogLabel('newEmpty')+'</p>';host.querySelectorAll('[data-id]').forEach(button=>button.onclick=()=>chooseService(Number(button.dataset.id)))}
