function cleanServiceName(value){const brands={instagram:'Instagram',tiktok:'TikTok',youtube:'YouTube',telegram:'Telegram',facebook:'Facebook',twitter:'Twitter',spotify:'Spotify',twitch:'Twitch',whatsapp:'WhatsApp',soundcloud:'SoundCloud',yandexmusic:'Yandex Music',rutube:'RuTube',linkedin:'LinkedIn',linkedÄ±n:'LinkedIn',github:'GitHub',applemusic:'Apple Music',yandexzen:'Yandex Zen',dzen:'Dzen',shopee:'Shopee',snapchat:'Snapchat',bluesky:'Bluesky',threads:'Threads',pinterest:'Pinterest',reddit:'Reddit',discord:'Discord',rumble:'Rumble',kick:'Kick',tumblr:'Tumblr',medium:'Medium',likee:'Likee',wibes:'Wibes',audiomack:'Audiomack',quora:'Quora',vk:'VK',okru:'OK.ru',x:'X',iphone:'iPhone',ios:'iOS',ebay:'eBay',paypal:'PayPal'};return String(value||'').replace(/\s+/g,' ').replace(/\p{L}[\p{L}\p{M}]*/gu,word=>{const key=word.toLocaleLowerCase('tr-TR');if(brands[key])return brands[key];const lower=word.toLocaleLowerCase('tr-TR');if(word.length<2||(word===word.toLocaleUpperCase('tr-TR')&&/^(hq|spam|api|seo|vip|usa|uk|us|eu|hd|id|url|dm|otp|faq|qr|vpn|ab|abd|ig|tt|yt|rt|usd|eur|try)$/u.test(lower)))return word;return lower[0].toLocaleUpperCase('tr-TR')+lower.slice(1)}).trim()}
